+	template <typename SAVE_TYPE, typename TARGET_TYPE>
+	static void Decode(const SAVE_TYPE &source, TARGET_TYPE &target, const LogicalType &type) {
+		Decode(source, target);
+		if (type.id() != LogicalTypeId::DECIMAL) {
+			return;
