+		copy = make_unsafe_uniq_array_uninitialized<T>(count);
+		memcpy(static_cast<void *>(copy.get()), source, count * sizeof(T));
+		data = copy.get();
+	}
+
+	const T &operator[](idx_t idx) const {
+		return data[idx];
+	}
+	const T *get() const {
+		return data;
+	}
+
+private:
+	const T *data;
+	unsafe_unique_array<T> copy;
