+		static constexpr idx_t MINIMUM_KEYS = 1024;
+		for (idx_t keys = MaximumKeyCount(key_count); keys >= MINIMUM_KEYS; keys /= 2) {
+			try {
+				data = allocator.Allocate(keys * key_size);
+				count = keys;
+				return;
+			} catch (OutOfMemoryException &) {
