+					++right_it;
+				} else {
+					*out = std::move(*buffer_it);
+					++buffer_it;
+				}
+				++out;
+			}
+			std::move(buffer_it, buffer_end, out);
+			return;
+		}
+		if (right_count <= buffer_count) {
+			// move the right side out and merge backward into [first, last)
+			std::move(middle, last, buffer);
