+		if (new_middle - first < last - new_middle) {
+			BufferedMerge<SORT_KEY>(first, first_cut, new_middle, compare, buffer, buffer_count);
+			first = new_middle;
+			middle = second_cut;
+		} else {
+			BufferedMerge<SORT_KEY>(new_middle, second_cut, last, compare, buffer, buffer_count);
+			last = new_middle;
+			middle = first_cut;
+		}
+	}
